"""The standards catalogue (SHIELD SH-60), generated by `make specs` from agentspecs' standards/."""

from agent_runtimes.specs.standards import (
    STANDARD_CATALOGUE,
    control_of,
    get_standard,
    list_standards,
)


def test_the_catalogue_carries_aiuc_1_and_iso_42001_whole():
    assert set(STANDARD_CATALOGUE) == {"aiuc-1", "iso-42001"}
    aiuc = get_standard("aiuc-1")
    assert aiuc is not None and aiuc.version == "2026.4" and len(aiuc.controls) == 55
    assert [d["id"] for d in aiuc.domains] == ["A", "B", "C", "D", "E", "F"]
    assert aiuc.next_release_on == "2027-01-15" and aiuc.read_on == "2026-10-15"
    d003 = control_of("aiuc-1", "D003")
    assert d003 is not None and d003["title"] == "Restrict unsafe tool calls"
    assert [e["id"] for e in d003["evidence"]] == [
        "D003.1",
        "D003.2",
        "D003.3",
        "D003.4",
        "D003.5",
    ]
    assert d003["crosswalks"]["nist-ai-rmf"] == [
        "GOVERN 6.1: Third-party risk policies"
    ]
    iso = get_standard("iso-42001")
    assert iso is not None and iso.maps_to == "aiuc-1" and len(iso.controls) == 70
    assert control_of("iso-42001", "A.10.3")["covered_by"] == ["E006"]
    assert control_of("aiuc-1", "Z999") is None and len(list_standards()) == 2
